// Shared behavior: mobile nav, footer year, and publication rendering
// from data/publications.js (generated by scripts_new_lab_website/).

(function () {
  const toggle = document.querySelector(".nav-toggle");
  const nav = document.querySelector(".nav");
  if (toggle && nav) {
    toggle.addEventListener("click", () => {
      const open = nav.classList.toggle("open");
      toggle.setAttribute("aria-expanded", String(open));
    });
  }
  document.querySelectorAll("[data-year]").forEach((el) => {
    el.textContent = new Date().getFullYear();
  });

  const PUBS = (window.PUBLICATIONS || []).slice().sort((a, b) => b.year - a.year);

  // Binomials first so the epithet is italicized with its genus.
  const BINOMIALS = ["Dendroctonus frontalis", "Daphnia pulex", "Culex quinquefasciatus",
    "Arabidopsis thaliana", "Pinus taeda", "Homo sapiens"];
  const GENERA = ["Arabidopsis", "Brassica", "Dendroctonus", "Drosophila", "Daphnia",
    "Culex", "Pelophylax", "Rana", "Pinus", "Picea", "Pseudotsuga", "Saccharomyces",
    "Populus", "Eucalyptus", "Mus", "Homo"];
  const SPECIES_RE = new RegExp("\\b(" + BINOMIALS.concat(GENERA).join("|") + ")\\b", "gi");
  const canonical = (m) => BINOMIALS.concat(GENERA).find((s) => s.toLowerCase() === m.toLowerCase()) || m;

  const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

  function formatTitle(t) {
    return esc(t)
      .replace(SPECIES_RE, (m) => "<i>" + canonical(m) + "</i>")
      .replace(/\bC([34])(?= )/g, "C<sub>$1</sub>");
  }

  function formatAuthors(s, full) {
    const names = s.split(/,\s*/);
    const bold = (n) => (/^Casola C$/.test(n) ? "<b>" + esc(n) + "</b>" : esc(n));
    if (full || names.length <= 12) return names.map(bold).join(", ");
    const i = names.findIndex((n) => n === "Casola C");
    const shown = names.slice(0, 3).map(bold);
    if (i >= 3 && i < names.length - 1) shown.push("…", bold(names[i]));
    shown.push("…", bold(names[names.length - 1]));
    return shown.join(", ") + ` <span class="pub-count">(${names.length} authors)</span>`;
  }

  function pubHTML(p, full) {
    const link = p.doi ? `https://doi.org/${p.doi}` : `https://pubmed.ncbi.nlm.nih.gov/${p.pmid}/`;
    return `<li class="pub">
      <div class="pub-title"><a href="${link}">${formatTitle(p.title)}</a>${p.preprint ? '<span class="tag">Preprint</span>' : ""}</div>
      <div class="pub-authors">${formatAuthors(p.authors, full)}</div>
      <div class="pub-venue"><i class="journal">${esc(p.journal)}</i> ${p.year}</div>
    </li>`;
  }

  // Shared with the scroll edition (scroll/), so both format titles identically.
  window.LabFormat = { esc, formatTitle, pubs: PUBS };

  // Home page: most recent papers.
  const recent = document.getElementById("recent-pubs");
  if (recent) {
    const n = Number(recent.dataset.count || 5);
    recent.innerHTML = PUBS.slice(0, n).map((p) => pubHTML(p, false)).join("");
  }

  // Research page: key papers per area, by DOI.
  document.querySelectorAll("[data-dois]").forEach((ul) => {
    const dois = ul.dataset.dois.split(/\s+/).filter(Boolean);
    ul.innerHTML = dois.map((d) => {
      const p = PUBS.find((x) => x.doi.toLowerCase() === d.toLowerCase());
      if (!p) { console.warn("DOI not in publications data:", d); return ""; }
      const surnames = p.authors.split(/,\s*/).map((n) => n.replace(/ \S+$/, ""));
      const cite = surnames.length > 2 ? surnames[0] + " et al." : surnames.join(" & ");
      return `<li>${esc(cite)} (${p.year}) <a href="https://doi.org/${p.doi}">${formatTitle(p.title)}</a>. <i>${esc(p.journal)}</i>${p.preprint ? " (preprint)" : ""}</li>`;
    }).join("");
  });

  // News page: hand-written items from data/news.js plus papers since 2022.
  const newsList = document.getElementById("news-list");
  if (newsList) {
    const MONTHS = ["January", "February", "March", "April", "May", "June", "July",
      "August", "September", "October", "November", "December"];
    const fmtDate = (d) => { const [y, m] = d.split("-"); return m ? `${MONTHS[Number(m) - 1]} ${y}` : y; };
    // Credit line is built from the publication record, so it cannot drift from it.
    const paperFigure = (p) => {
      const f = (window.NEWS_FIGURES || {})[p.doi];
      if (!f) return null;
      const s = p.authors.split(/,\s*/).map((n) => n.replace(/ \S+$/, ""));
      const cite = s.length > 2 ? s[0] + " et al." : s.join(" & ");
      return { src: "assets/img/news/" + f.file, alt: `${f.label} from ${p.title}`,
        credit: `${f.label}, ${esc(cite)} ${p.year}, <i>${esc(p.journal)}</i>${f.license ? ", " + f.license : ""}` };
    };
    const items = (window.NEWS || []).map((n) => ({
      date: n.date, kicker: "Lab news", title: esc(n.title), text: n.text || "",
      image: n.image,
    })).concat(PUBS.filter((p) => p.date >= "2022").map((p) => ({
      date: p.date, image: paperFigure(p),
      kicker: p.preprint ? "New preprint" : "New paper",
      title: `<a href="https://doi.org/${p.doi}">${formatTitle(p.title)}</a>`,
      text: `<i>${esc(p.journal)}</i>`,
    })));
    items.sort((a, b) => b.date.localeCompare(a.date));
    // A missing image file removes its figure, so the item falls back to text only.
    const figHTML = (im) => !im ? "" : `<figure class="news-fig${im.photo ? " photo" : ""}">
      <a href="${im.src}"><img src="${im.src}" alt="${esc(im.alt || "")}" loading="lazy"
        ${im.credit ? `title="${im.credit.replace(/<[^>]+>/g, "")}"` : ""}
        onerror="this.closest('.news-item').classList.remove('has-fig');this.closest('figure').remove()"></a></figure>`;
    newsList.innerHTML = items.map((n) => `<li class="news-item${n.image ? " has-fig" : ""}">
      <div class="news-date">${fmtDate(n.date)}</div>
      <div><div class="news-kicker">${n.kicker}</div><h3>${n.title}</h3>${n.text ? `<p>${n.text}</p>` : ""}</div>
      ${figHTML(n.image)}
    </li>`).join("");
  }

  // Publications page: full list with search.
  const list = document.getElementById("pub-list");
  if (list) {
    const search = document.getElementById("pub-search");
    const full = document.getElementById("pub-full");
    const count = document.getElementById("pub-count");
    const render = () => {
      const q = (search.value || "").toLowerCase().trim();
      const hits = PUBS.filter((p) => !q || [p.title, p.authors, p.journal, String(p.year)].join(" ").toLowerCase().includes(q));
      count.textContent = `${hits.length} of ${PUBS.length} publications`;
      let html = "", year = null;
      hits.forEach((p) => {
        if (p.year !== year) {
          if (year !== null) html += "</ul>";
          year = p.year;
          html += `<h2 class="year">${year}</h2><ul class="pubs">`;
        }
        html += pubHTML(p, full.checked);
      });
      list.innerHTML = html + (year !== null ? "</ul>" : "<p>No matching publications.</p>");
    };
    search.addEventListener("input", render);
    full.addEventListener("change", render);
    render();
  }
})();
